288	     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
289	     * proportion to the line amounts: each line first gets the whole cents of its exact share
290	     * (rounded down), then the cents left over go one each to the lines with the largest leftover
291	     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
292	     * equal amounts too to the lower line id. The shares add up to the discount.
293	     */
294	    public List<BigDecimal> discountShares() {
295	        BigInteger discountCents = discount().movePointRight(2).toBigIntegerExact();
296	        BigInteger subtotalCents = subtotal().movePointRight(2).toBigIntegerExact();
297	        int n = lines.size();
298	        BigInteger[] shares = new BigInteger[n];
299	        BigInteger[] leftovers = new BigInteger[n];
300	        BigInteger given = BigInteger.ZERO;
301	        for (int i = 0; i < n; i++) {
302	            if (subtotalCents.signum() == 0) {
303	                shares[i] = BigInteger.ZERO;
304	                leftovers[i] = BigInteger.ZERO;
305	            } else {
306	                // The exact share is discount * amount / subtotal; all fractions share the subtotal
307	                // as denominator, so the remainders compare as the fractions do.
308	                BigInteger[] qr = discountCents.multiply(lines.get(i).amount().movePointRight(2).toBigIntegerExact())
309	                        .divideAndRemainder(subtotalCents);
310	                shares[i] = qr[0];
311	                leftovers[i] = qr[1];
312	            }
313	            given = given.add(shares[i]);
314	        }
315	        List<Integer> order = new ArrayList<>();
316	        for (int i = 0; i < n; i++) {
317	            order.add(i);
318	        }
319	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
320	                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount()).reversed())
321	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
322	        int left = discountCents.subtract(given).intValueExact();
323	        for (int k = 0; k < left; k++) {
324	            int i = order.get(k);
325	            shares[i] = shares[i].add(BigInteger.ONE);
326	        }
327	        List<BigDecimal> result = new ArrayList<>(n);
328	        for (BigInteger share : shares) {
329	            result.add(new BigDecimal(share, 2));
330	        }
331	        return result;
332	    }
