340	        List<BigDecimal> shares = discountShares();
341	        List<BigDecimal> taxes = new ArrayList<>(lines.size());
342	        for (int i = 0; i < lines.size(); i++) {
343	            InvoiceLine line = lines.get(i);
344	            taxes.add(line.isTaxExempt() ? BigDecimal.ZERO.setScale(2)
345	                    : line.amount().subtract(shares.get(i)).multiply(line.taxRate(taxRate)).divide(BigDecimal.valueOf(100))
346	                            .setScale(2, RoundingMode.HALF_UP));
347	        }
348	        return taxes;
349	    }
