22	/**
23	 * Lists a client's invoices, opens one, starts new drafts, duplicates one, adds lines to them, gives them a discount,
24	 * sends them, voids them and records payments against them.
25	 */
26	@Service
27	public class InvoiceService {
28	
29	    private final InvoiceRepository invoices;
30	    private final PaymentRepository payments;
31	    private final ClientRepository clients;
32	    private final Today today;
33	    private final TaxRate taxRate;
34	    private final Audit audit;
35	
36	    public InvoiceService(InvoiceRepository invoices, PaymentRepository payments, ClientRepository clients,
37	            Today today, TaxRate taxRate, Audit audit) {
38	        this.invoices = invoices;
39	        this.payments = payments;
40	        this.clients = clients;
41	        this.today = today;
42	        this.taxRate = taxRate;
43	        this.audit = audit;
44	    }
45	
46	    @Transactional(readOnly = true)
47	    public List<Invoice> forClient(Long clientId) {
48	        return invoices.findByClientIdOrderByIdAsc(clientId);
49	    }
50	
51	    /** Every invoice of every client, with its lines. */
52	    @Transactional(readOnly = true)
53	    public List<Invoice> all() {
54	        return invoices.findAllByOrderByIdAsc();
55	    }
56	
57	    @Transactional(readOnly = true)
58	    public Optional<Invoice> find(Long id) {
59	        return invoices.findWithLinesById(id);
60	    }
61	
62	    /** An empty draft for the client, issued today and due on the client's terms; empty if no such client. */
63	    @Transactional
64	    public Optional<Invoice> newDraft(Long clientId) {
65	        if (!clients.existsById(clientId)) {
66	            return Optional.empty();
67	        }
68	        LocalDate issued = today.date();
69	        return Optional.of(invoices.save(Invoice.draft(clientId, issued, dueDateFor(clientId, issued))));
70	    }
71	
72	    /**
73	     * A new draft for the invoice's client with copies of its lines and the same invoice discount,
74	     * issued today and due as any new invoice is, and records it in the audit; empty if no such
75	     * invoice. Payments are not copied.
76	     */
77	    @Transactional
78	    public Optional<Invoice> duplicate(Long invoiceId) {
79	        return invoices.findWithLinesById(invoiceId).map(original -> {
80	            LocalDate issued = today.date();
81	            Invoice copy = invoices.saveAndFlush(original.duplicate(issued, dueDateFor(original.getClientId(), issued)));
82	            audit.record("INVOICE_DUPLICATED from=" + InvoiceNumber.of(original.getId())
83	                    + " to=" + InvoiceNumber.of(copy.getId()));
84	            return copy;
85	        });
86	    }
87	
88	    /**
89	     * An invoice for a client with payment terms is due that many days after it is issued; otherwise
90	     * as {@link #dueDateFor(LocalDate)}.
91	     */
92	    private LocalDate dueDateFor(Long clientId, LocalDate issued) {
93	        return clients.findById(clientId)
94	                .map(Client::getTermsDays)
95	                .map(days -> issued.plusDays(days))
96	                .orElseGet(() -> dueDateFor(issued));
97	    }
98	
99	    /** A new invoice is due on the last day of the month after the month it is issued in. */
100	    static LocalDate dueDateFor(LocalDate issued) {
101	        LocalDate nextMonth = issued.plusMonths(1);
102	        return nextMonth.withDayOfMonth(nextMonth.lengthOfMonth());
103	    }
104	
105	    /**
106	     * Adds a line to an invoice; empty if no such invoice. The line has already been checked. A sent
107	     * invoice with no payments goes back to draft; one with a payment refuses it.
108	     */
109	    @Transactional
110	    public Optional<Invoice> addLine(Long invoiceId, String description, BigDecimal qty, BigDecimal unitPrice,
111	            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
112	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
113	        found.ifPresent(invoice -> {
114	            boolean reopened = reopenForChange(invoice, "A paid invoice cannot take new lines.");
115	            invoice.addLine(new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate));
116	            invoices.saveAndFlush(invoice);
117	            if (reopened) {
118	                audit.record("INVOICE_REOPENED id=" + invoice.getId());
119	            }
120	        });
121	        return found;
122	    }
123	
124	    /**
125	     * Removes a line from an invoice; empty if no such invoice or line. Refused when what is left would
126	     * be less than a fixed discount. A sent invoice with no payments goes back to draft; one with a
127	     * payment refuses it.
128	     */
129	    @Transactional
130	    public Optional<Invoice> removeLine(Long invoiceId, Long lineId) {
131	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
132	        if (found.isEmpty()) {
133	            return found;
134	        }
135	        Invoice invoice = found.get();
136	        if (!invoice.hasLine(lineId)) {
137	            return Optional.empty();
138	        }
139	        boolean reopened = reopenForChange(invoice, "A paid invoice cannot have lines removed.");
140	        invoice.removeLine(lineId);
141	        invoices.saveAndFlush(invoice);
142	        if (reopened) {
143	            audit.record("INVOICE_REOPENED id=" + invoice.getId());
144	        }
145	        return found;
146	    }
147	
148	    /**
149	     * Gives an invoice a percentage discount, or a fixed amount off when one is given; the one given
150	     * clears the other, and the cap (null for none) limits everything taken off, line discounts included. Empty if no such invoice. The values have already been checked; a fixed amount
151	     * over the subtotal is refused. A sent invoice with no payments goes back to draft; one with a
152	     * payment refuses it.
153	     */
154	    @Transactional
155	    public Optional<Invoice> setDiscount(Long invoiceId, BigDecimal discountPct, BigDecimal discountAmount,
156	            BigDecimal discountCap) {
157	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
158	        found.ifPresent(invoice -> {
159	            boolean reopened = reopenForChange(invoice, "A paid invoice cannot be given a discount.");
160	            if (discountAmount != null) {
161	                invoice.setDiscountAmount(discountAmount);
162	            } else {
163	                invoice.setDiscountPct(discountPct);
164	            }
165	            invoice.setDiscountCap(discountCap);
166	            invoices.saveAndFlush(invoice);
167	            if (reopened) {
168	                audit.record("INVOICE_REOPENED id=" + invoice.getId());
169	            }
170	        });
171	        return found;
172	    }
173	
174	    /**
175	     * Readies the invoice for a change: a draft stays as it is; a sent invoice with no payments goes
176	     * back to draft, to be sent again; an invoice with any payment is refused with the message.
177	     * Whether it went back to draft.
178	     */
179	    private boolean reopenForChange(Invoice invoice, String refusal) {
180	        if (invoice.isDraft()) {
181	            return false;
182	        }
183	        if (invoice.isVoid()) {
184	            throw new InvoiceRejectedException("A void invoice cannot be changed.");
185	        }
186	        if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
187	            throw new InvoiceRejectedException(refusal);
188	        }
189	        invoice.reopen();
190	        return true;
191	    }
192	
193	    /**
194	     * Sends a draft invoice, issuing it today and making it due on the client's terms, and records it in the audit; empty if
195	     * no such invoice. An invoice already sent, or with no lines, is refused.
196	     */
197	    @Transactional
198	    public Optional<Invoice> send(Long invoiceId) {
199	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
200	        found.ifPresent(invoice -> {
201	            if (invoice.isVoid()) {
202	                throw new InvoiceRejectedException("A void invoice cannot be sent.");
203	            }
204	            if (!invoice.isDraft()) {
205	                throw new InvoiceRejectedException("This invoice has already been sent.");
206	            }
207	            if (invoice.getLines().isEmpty()) {
208	                throw new InvoiceRejectedException("Add at least one line before sending the invoice.");
209	            }
210	            markSent(invoice);
211	        });
212	        return found;
213	    }
214	
215	    /**
216	     * Sends each of the client's drafts that has at least one line, lowest id first, as {@link #send}
217	     * would; drafts with no lines stay drafts.
218	     */
219	    @Transactional
220	    public void sendAllDrafts(Long clientId) {
221	        invoices.findByClientIdOrderByIdAsc(clientId).stream()
222	                .filter(invoice -> invoice.isDraft() && !invoice.getLines().isEmpty())
223	                .forEach(this::markSent);
224	    }
225	
226	    /** Issues the draft today, due on the client's terms, and records it in the audit. */
227	    private void markSent(Invoice invoice) {
228	        LocalDate issued = today.date();
229	        invoice.markSent(issued, dueDateFor(invoice.getClientId(), issued));
230	        invoices.saveAndFlush(invoice);
231	        audit.record("INVOICE_SENT id=" + invoice.getId() + " number=" + InvoiceNumber.of(invoice.getId())
232	                + " total=" + invoice.total(taxRate.percent()).toPlainString());
233	    }
234	
235	    /**
236	     * Voids a sent invoice with no payments, and records it in the audit; empty if no such invoice. A
237	     * draft, an invoice already void, or one with any payment is refused.
238	     */
239	    @Transactional
240	    public Optional<Invoice> voidInvoice(Long invoiceId) {
241	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
242	        found.ifPresent(invoice -> {
243	            if (invoice.isVoid()) {
244	                throw new InvoiceRejectedException("This invoice is already void.");
245	            }
246	            if (invoice.isDraft()) {
247	                throw new InvoiceRejectedException("A draft cannot be voided; only a sent invoice can.");
248	            }
249	            if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
250	                throw new InvoiceRejectedException("An invoice with payments cannot be voided.");
251	            }
252	            invoice.markVoid();
253	            invoices.saveAndFlush(invoice);
254	            audit.record("INVOICE_VOIDED id=" + invoice.getId() + " number=" + InvoiceNumber.of(invoice.getId()));
255	        });
256	        return found;
257	    }
258	
259	    /** The payments made to the invoice, oldest first, with their allocations. */
260	    @Transactional(readOnly = true)
261	    public List<Payment> payments(Long invoiceId) {
262	        return payments.findForInvoice(invoiceId);
263	    }
264	
265	    /** The date each fully paid invoice was paid (see {@link Invoice#paidOn}); an invoice not fully paid is left out. */
266	    @Transactional(readOnly = true)
267	    public Map<Long, LocalDate> paidOn(List<Invoice> list) {
268	        Map<Long, LocalDate> paidOn = new HashMap<>();
269	        if (list.isEmpty()) {
270	            return paidOn;
271	        }
272	        List<Payment> found = payments.findForInvoices(list.stream().map(Invoice::getId).toList());
273	        BigDecimal rate = taxRate.percent();
274	        for (Invoice i : list) {
275	            LocalDate on = i.paidOn(found, rate);
276	            if (on != null) {
277	                paidOn.put(i.getId(), on);
278	            }
279	        }
280	        return paidOn;
281	    }
282	
283	    /** What has been paid to each of the invoices; an invoice paid nothing is paid zero. */
284	    @Transactional(readOnly = true)
285	    public Map<Long, BigDecimal> paid(List<Invoice> list) {
286	        Map<Long, BigDecimal> paid = new HashMap<>();
287	        list.forEach(i -> paid.put(i.getId(), BigDecimal.ZERO.setScale(2)));
288	        if (!list.isEmpty()) {
289	            for (Object[] row : payments.paidTo(list.stream().map(Invoice::getId).toList())) {
290	                paid.put((Long) row[0], ((BigDecimal) row[1]).setScale(2));
291	            }
292	        }
293	        return paid;
294	    }
295	
296	    /**
297	     * Records a payment of the amount on the date against a sent invoice that still has something
298	     * due, and records it in the audit; empty if no such invoice. The amount has already been
299	     * checked; a draft, an invoice already paid, an amount over what is due, or a date after today
300	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
301	     * already been checked; one that belongs to a different invoice is refused.
302	     */
303	    @Transactional
304	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal amount, LocalDate date, String reference) {
305	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
306	        found.ifPresent(invoice -> {
307	            if (invoice.isDraft()) {
308	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
309	            }
310	            if (invoice.isVoid()) {
311	                throw new InvoiceRejectedException("A void invoice takes no payments.");
312	            }
313	            BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
314	            if (due.signum() <= 0) {
315	                throw new InvoiceRejectedException("This invoice has already been paid.");
316	            }
317	            if (amount.compareTo(due) > 0) {
318	                throw new InvoiceRejectedException("The payment is more than the $" + due.toPlainString() + " due.");
319	            }
320	            LocalDate now = today.date();
321	            if (date.isAfter(now)) {
322	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
